import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Stage 2 · Personal Operator","description":"Hearth Stage 2 开发模块：只读连接器、文档与数据执行、网页研究、草稿审批、Context Compiler、Token Governor 与 Memory v0。","frontmatter":{"title":"Stage 2 · Personal Operator","description":"Hearth Stage 2 开发模块：只读连接器、文档与数据执行、网页研究、草稿审批、Context Compiler、Token Governor 与 Memory v0。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2.md","filePath":"delivery/stage-2.md","lastUpdated":1793752688000}'),l={name:"delivery/stage-2.md"};function i(d,t,n,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<p class="eyebrow">MODULE 2 / 7</p><h1 id="stage-2-·-personal-operator" tabindex="-1">Stage 2 · Personal Operator <a class="header-anchor" href="#stage-2-·-personal-operator" aria-label="Permalink to &quot;Stage 2 · Personal Operator&quot;">​</a></h1><p class="lead">从“能完成文件任务”扩展到“能承担大多数日常内容工作”。顺序必须先只读、再确定性处理、再网页、最后测试账户下的真实写入，避免一开始就把高风险账户交给模型。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>Stage 1 的持久任务、审批、幂等、回执和恢复已经稳定。</li><li>已选定首批连接器与文档/数据任务，并准备测试账户。</li><li>所有外部来源都进入统一 Source 模型，保留权限、来源和审计信息。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>连接只读来源。</strong> 先接邮件、日历、文件和知识库的只读同步，建立来源视图、去重、增量和权限校验。</li><li><strong>加入 Document/Data Executor。</strong> 支持文档转换、表格处理、结构化提取、引用定位和可验证产物。</li><li><strong>加入 Browser Executor。</strong> 先做公开网页研究、引用和页面 diff；隔离登录态，处理不可信页面和提示词注入。</li><li><strong>打通测试账户副作用。</strong> 用测试账户完成“读—理解—起草—审批—发送/写入—回执”闭环，验证幂等、失败对账和撤销。</li><li><strong>编译上下文与预算。</strong> 引入 Context Compiler、Token Governor v1 和 Memory v0；记录召回来源、Token 消耗和人工分钟。</li><li><strong>完成 Stage 2 发布。</strong> 用代表性日常任务评估成功率、人工分钟、跨账户隔离、失败恢复和用户信任。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td>D2.1 只读连接器与来源视图</td><td>用户能看到邮件、日历、文件和知识库来源</td><td>同步、去重、增量、权限与来源审计</td></tr><tr><td>D2.2 Document/Data Executor</td><td>文档与表格可转换、提取并验证</td><td>产物、引用、结构和失败样本</td></tr><tr><td>D2.3 Browser Executor 与网页研究</td><td>网页研究有来源、引用和页面变化证据</td><td>隔离登录态、网页 diff、注入防护</td></tr><tr><td>D2.4 草稿、审批与测试账户副作用</td><td>用户能审批发送/写入并查看回执</td><td>测试账户闭环、幂等、对账、撤销</td></tr><tr><td>D2.5 Context Compiler 与 Memory v0</td><td>任务使用更少上下文且能解释召回</td><td>Token 基线、召回来源、预算与降级</td></tr><tr><td>D2.6 Stage 2 发布</td><td>日常内容任务的人工分钟显著下降</td><td>真实任务评估、跨账户隔离、安全报告</td></tr></tbody></table><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] 邮件“读—理解—起草—审批—发送—回执”闭环可用。</li><li>[ ] 日历冲突检查与待审批写入可用。</li><li>[ ] 文档转换、数据提取和网页研究结果可验证，来源可追溯。</li><li>[ ] 常见任务的人工分钟显著下降，Token 有基线。</li><li>[ ] 没有跨账户、跨项目数据串扰；失败时能恢复或明确转人工。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不直接接管无隔离的真实主账户。</li><li>不为了连接器数量牺牲权限、幂等和回执。</li><li>不让不可信网页内容直接改变系统权限或审批策略。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>进入 <a href="/hearth-os/delivery/stage-3.html">Stage 3 · Computer Operator</a>，处理没有 API 的桌面软件。</p>',15)])])}const g=e(l,[["render",i]]);export{p as __pageData,g as default};
